solution.solution.py:
from abc import ABC, abstractmethod


class Exporter(ABC):
    formats = {}

    def __init_subclass__(cls, fmt, **kwargs):
        super().__init_subclass__(**kwargs)
        if fmt in Exporter.formats:
            raise ValueError(f"format {fmt!r} is already registered")
        Exporter.formats[fmt] = cls

    @abstractmethod
    def export(self, rows):
        ...


class CsvExporter(Exporter, fmt="csv"):
    def export(self, rows):
        if not rows:
            return ""
        keys = list(rows[0])
        lines = [",".join(keys)]
        lines += [",".join(str(row[k]) for k in keys) for row in rows]
        return "".join(line + "\n" for line in lines)


class MarkdownExporter(Exporter, fmt="md"):
    def export(self, rows):
        if not rows:
            return ""
        keys = list(rows[0])
        lines = ["| " + " | ".join(keys) + " |", "|" + "---|" * len(keys)]
        lines += ["| " + " | ".join(str(row[k]) for k in keys) + " |" for row in rows]
        return "".join(line + "\n" for line in lines)


def export_as(fmt, rows):
    return Exporter.formats[fmt]().export(rows)

unitTests:
ROWS = [{"name": "Ada", "age": 36}, {"name": "Alan", "age": 41}]

@test("csv")
def _():
    check_eq(export_as("csv", ROWS), "name,age\nAda,36\nAlan,41\n")
    check_eq(export_as("csv", []), "")

@test("markdown")
def _():
    check_eq(export_as("md", ROWS), "| name | age |\n|---|---|\n| Ada | 36 |\n| Alan | 41 |\n")

@test("registration")
def _():
    check_eq(sorted(Exporter.formats), ["csv", "md"])
    check_raises(KeyError, export_as, "xml", ROWS)
    def duplicate():
        class Again(Exporter, fmt="csv"):
            def export(self, rows):
                return ""
    check_raises(ValueError, duplicate)

@test("abstract")
def _():
    check_raises(TypeError, Exporter)
    def forgot():
        class Lazy(Exporter, fmt="lazy"):
            pass
        return Lazy()
    check_raises(TypeError, forgot)
    Exporter.formats.pop("lazy", None)

